package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class AlarmTonePreviewTest {
    static final class Fake implements AlarmTonePreview.Port {final List<Session> sessions=new ArrayList<>();boolean synchronous;int closes;public AlarmTonePreview.Session open(String tone,float gain,AlarmTonePreview.Events events){Session session=new Session(tone,gain,events);sessions.add(session);if(synchronous)events.ready();return session;}public void close(){closes++;}}
    static final class Session implements AlarmTonePreview.Session {final String tone;final AlarmTonePreview.Events events;float gain;int plays,pauses,closes;Session(String tone,float gain,AlarmTonePreview.Events events){this.tone=tone;this.gain=gain;this.events=events;}public void play(){plays++;events.playing();}public void pause(){pauses++;events.paused();}public void gain(float gain){this.gain=gain;}public void close(){closes++;}}
    @Test public void noOutputAllocationBeforeVisibleExplicitPlay(){Fake fake=new Fake();AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.toggle("daybreak");p.volume(20);assertTrue(fake.sessions.isEmpty());p.visible(true);assertTrue(fake.sessions.isEmpty());p.toggle("daybreak");assertEquals(1,fake.sessions.size());assertEquals(0,fake.sessions.get(0).plays);fake.sessions.get(0).events.ready();assertEquals(1,fake.sessions.get(0).plays);p.close();}
    @Test public void quietGainIsBoundedIndependentlyOfToneAndResumesOnlyExplicitly(){Fake fake=new Fake();fake.synchronous=true;AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.visible(true);p.volume(100);p.toggle("pulse");Session s=fake.sessions.get(0);assertEquals(.25f,s.gain,0);assertEquals(1,s.plays);p.toggle("pulse");assertEquals(AlarmTonePreview.Phase.PAUSED,p.phase());assertEquals(1,s.pauses);p.volume(-1);assertEquals(0,s.gain,0);assertEquals(1,s.plays);p.toggle("pulse");assertEquals(2,s.plays);p.close();}
    @Test public void switchingClosesPreviousAndLateCallbacksCannotRestartIt(){Fake fake=new Fake();AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.visible(true);p.toggle("daybreak");Session first=fake.sessions.get(0);p.toggle("chime");assertEquals(1,first.closes);first.events.ready();first.events.playing();assertEquals(0,first.plays);assertEquals("chime",p.tone());assertEquals(AlarmTonePreview.Phase.LOADING,p.phase());p.close();}
    @Test public void loadingPauseIsCancellationNotDeferredPlayback(){Fake fake=new Fake();AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.visible(true);p.toggle("pulse");Session s=fake.sessions.get(0);p.toggle("pulse");assertEquals(AlarmTonePreview.Phase.STOPPED,p.phase());s.events.ready();assertEquals(0,s.plays);assertEquals(1,s.closes);p.close();}
    @Test public void hiddenAndClosedOwnersFenceReadyPlayErrorAndEnd(){Fake fake=new Fake();AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.visible(true);p.toggle("daybreak");Session s=fake.sessions.get(0);p.visible(false);s.events.ready();s.events.failed("late");assertEquals(AlarmTonePreview.Phase.STOPPED,p.phase());assertEquals("",p.error());p.visible(true);assertEquals(0,s.plays);p.close();p.close();p.toggle("chime");assertEquals(1,fake.sessions.size());assertEquals(1,fake.closes);}
    @Test public void failureAndCompletionReleaseSessionWithoutChangingVolume(){Fake fake=new Fake();AlarmTonePreview p=new AlarmTonePreview(fake,()->{});p.visible(true);p.volume(7);p.toggle("daybreak");Session s=fake.sessions.get(0);s.events.failed("Audio busy");assertEquals(AlarmTonePreview.Phase.ERROR,p.phase());assertEquals("Audio busy",p.error());assertEquals(1,s.closes);p.toggle("pulse");Session next=fake.sessions.get(1);next.events.ready();next.events.ended();assertEquals(AlarmTonePreview.Phase.STOPPED,p.phase());assertEquals(7,p.volume());assertEquals(1,next.closes);p.close();}
    @Test public void toneMappingPreservesOriginalsAndRoutesNewChime(){assertEquals("daybreak.wav",AlarmTones.asset("daybreak"));assertEquals("pulse.wav",AlarmTones.asset("pulse"));assertEquals("chime.wav",AlarmTones.asset("chime"));assertEquals("daybreak.wav",AlarmTones.asset("unknown legacy value"));assertEquals("Chime",AlarmTones.name("chime"));assertFalse(AlarmTones.bundled("system"));assertFalse(AlarmTones.bundled("content://audio/one"));}
    @Test public void selectedChimeReachesActualAlarmOrchestrationThroughInertSink(){Alarm alarm=new Alarm(1);alarm.tone="chime";alarm.rampSeconds=0;AlarmPlaybackTest.Fake sink=new AlarmPlaybackTest.Fake();AlarmPlayback engine=new AlarmPlayback(alarm,sink,()->0,()->0);engine.start();assertEquals("chime",sink.layers.get(0).tone);assertEquals("chime.wav",AlarmTones.asset(sink.layers.get(0).tone));sink.layers.get(0).callback.ready();assertEquals(1,sink.layers.get(0).starts);engine.stop();assertEquals(1,sink.stops);}
}
